import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (p < 0.05, |t| > 2)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat = feats.x[:, i].T @ feats.y / (np.std(feats.x[:, i]) * np.sqrt(np.mean(feats.y) * (1 - np.mean(feats.y))))
            if abs(t_stat) > 2 and feats.y.std() > 0:
                strong_features.append((fid, t_stat))

    # Sort by absolute t-statistic
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for correlated pairs
    correlations = {}
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(feats.ids[i], feats.ids[j])] = corr

    # Look for product terms among top features
    candidates = [f[0] for f in strong_features[:10]]
    best_product = None
    best_auc = 0

    # Try products of correlated pairs
    for (a, b), corr in correlations.items():
        if a in candidates and b in candidates:
            product_col = feats.x[:, feats.column(a)] * feats.x[:, feats.column(b)]
            try:
                auc = roc_auc_score(feats.y, product_col)
                if auc > best_auc:
                    best_auc = auc
                    best_product = (a, b)
            except:
                pass

    # If we found a good product term, return it
    if best_product and best_auc > 0.52:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )

    # Otherwise, return the top single feature
    if strong_features:
        return Design(
            drivers=(strong_features[0][0],),
            columns=(strong_features[0][0],),
            products=(),
            loadings={}
        )

    # No mechanism case
    return Design(drivers=(), columns=(), products=(), loadings={})

